import React from 'react';
import { useCart } from '../context/CartProvider';

const CartIcon = () => {
  const { cart } = useCart();

  return (
    <div>
      <i className="bi bi-cart"></i>
      {cart.length > 0 && (
        <span className="badge bg-danger">{cart.length}</span>
      )}
    </div>
  );
};

export default CartIcon;
